/**
 * Proposal document builder for TransYachtGroup.
 *
 * Accepts a vehicle record (same shape as GET /api/vehicles/:id) and an
 * optional set of validated photo URLs, and produces a DocumentModel that
 * the adaptive PDF engine renders into a 3-body-page PDF:
 *
 *   Cover  — full-bleed hero photo + logo + name + key stats
 *   Page 1 — specification grid (all available spec fields)
 *   Page 2 — photo gallery
 *   Page 3 — contact block
 *
 * AUTO-GENERATED in part — run scripts/gen-proposal-builder.mjs to refresh
 * the embedded logo whenever public/images/logo-transparent.png changes.
 */
import type { ContentNode, DocumentModel } from "../model/types";
import type { DocumentTemplate, ExportSettings } from "../documentTypes";
import { getTheme, adaptiveCss } from "../core/theme";
import { esc } from "../core/util";

// ─── types ───────────────────────────────────────────────────────────────────

/** Vehicle as returned by GET /api/vehicles/:id */
export interface VehicleRecord {
  id: number;
  name: string;
  category: string;
  description: string;
  image: string;
  images: string[];
  featured?: boolean;
  visible?: boolean;
  specs: Record<string, string>;
  translations?: Record<string, Record<string, unknown>>;
  createdAt?: string;
}

export interface ProposalContact {
  phone?: string;
  whatsapp?: string;
  email?: string;
  website?: string;
}

/** A specific rental quote — dates, rate, and total — for a single booking. */
export interface RentalDates {
  /** ISO date (YYYY-MM-DD) */
  start: string;
  /** ISO date (YYYY-MM-DD) */
  end: string;
  mode: "daily" | "monthly";
  /** Rate per day (daily mode) or per month (monthly mode). */
  rate: number;
  /** Number of days (daily mode) or months (monthly mode). */
  periods: number;
  total: number;
  /** HH:MM pickup time on `start` */
  pickupTime?: string;
  /** HH:MM return time on `end` */
  returnTime?: string;
  pickupLocation?: string;
  returnLocation?: string;
}

/** A one-off transfer/pickup booking — mutually exclusive with RentalDates. */
export interface TransferDetails {
  from: string;
  to: string;
  /** ISO date (YYYY-MM-DD) */
  date: string;
  /** HH:MM */
  time: string;
  passengers: number;
  price: number;
}

export interface BuildProposalInput {
  vehicle: VehicleRecord;
  /** Validated, reachable https photo URLs (pre-probed by generateDocument). */
  photos: string[];
  settings?: ExportSettings;
  template?: DocumentTemplate;
  /** Override contact details (fetched from CMS by the route layer). */
  contact?: ProposalContact;
  /** When set, the cover shows this specific quote instead of the generic spec price. */
  rentalDates?: RentalDates;
  /** When set, the cover shows a transfer summary instead of a rental quote. */
  transferDetails?: TransferDetails;
  /** Strips the logo, contact bar, and brand name — a clean proposal for agents to resell. */
  whiteLabel?: boolean;
}

