// ─── helpers ─────────────────────────────────────────────────────────────────

/** Strip HTML tags and decode common entities from CMS/rich-text fields. */
export function stripHtml(s: string | undefined): string {
  if (!s) return "";
  return (
    s
      // Block-level closing tags → newline so paragraphs stay separate
      .replace(
        /<\/(p|div|li|ul|ol|h[1-6]|blockquote|section|article|tr|td|th)>/gi,
        "\n",
      )
      .replace(/<br\s*\/?>/gi, "\n")
      // All remaining tags → space so adjacent words don't merge
      .replace(/<[^>]+>/g, " ")
      .replace(/&nbsp;/g, " ")
      .replace(/&amp;/g, "&")
      .replace(/&lt;/g, "<")
      .replace(/&gt;/g, ">")
      .replace(/&quot;/g, '"')
      .replace(/&#39;/g, "'")
      // Collapse runs of spaces/tabs on one line, then excess blank lines
      .replace(/[ \t]+/g, " ")
      .replace(/\n[ \t]+/g, "\n")
      .replace(/\n{3,}/g, "\n\n")
      .trim()
  );
}

const PRICE_KEYS = new Set([
  "pricePerDay",
  "pricePerWeek",
  "pricePerThreeDays",
  "pricePerMonth",
  "extraPricePerKm",
  "deposit",
]);

/** Strip HTML and append € prefix to price fields that lack a currency symbol. */
function fmtVal(key: string, raw: string): string {
  const s = stripHtml(raw);
  if (PRICE_KEYS.has(key) && s && !/[€$£₣]|CHF|EUR|USD|GBP/.test(s))
    return `€ ${s}`;
  return s;
}

/**
 * Reduce image bandwidth by capping the `w=` query param that CDNs like
 * Unsplash, Imgix, and Cloudflare Images understand. Never upscales.
 */
export function compressPhotoUrl(url: string, maxWidth: number): string {
  try {
    const u = new URL(url);
    const current = u.searchParams.get("w");
    if (!current || parseInt(current, 10) > maxWidth) {
      u.searchParams.set("w", String(maxWidth));
    }
    if (u.hostname.includes("unsplash.com") && !u.searchParams.has("q")) {
      u.searchParams.set("q", "70");
    }
    return u.toString();
  } catch {
    return url;
  }
}

function fmtEur(n: number, lang: Lang): string {
  return `€ ${n.toLocaleString(lang === "ru" ? "ru-RU" : "en-GB", { maximumFractionDigits: 2 })}`;
}

/** "10 June – 15 June 2026" / "28 November – 2 December 2026" / "28 December 2026 – 2 January 2027" */
function formatDateRange(startIso: string, endIso: string, lang: Lang): string {
  const locale = lang === "ru" ? "ru-RU" : "en-GB";
  const start = new Date(startIso + "T00:00:00");
  const end = new Date(endIso + "T00:00:00");
  const sameYear = start.getFullYear() === end.getFullYear();

  const startLabel = start.toLocaleDateString(locale, {
    day: "numeric",
    month: "long",
    year: sameYear ? undefined : "numeric",
  });
  const endLabel = end.toLocaleDateString(locale, {
    day: "numeric",
    month: "long",
    year: "numeric",
  });
  return `${startLabel} – ${endLabel}`;
}

/** "15 June 2026" */
function formatSingleDate(iso: string, lang: Lang): string {
  const locale = lang === "ru" ? "ru-RU" : "en-GB";
  const d = new Date(iso + "T00:00:00");
  return d.toLocaleDateString(locale, {
    day: "numeric",
    month: "long",
    year: "numeric",
  });
}

/** "17 Jul 2026" — used alongside a pickup/return time, where the full month name would run long. */
function formatDateShort(iso: string, lang: Lang): string {
  const locale = lang === "ru" ? "ru-RU" : "en-GB";
  const d = new Date(iso + "T00:00:00");
  return d.toLocaleDateString(locale, {
    day: "numeric",
    month: "short",
    year: "numeric",
  });
}

// ─── builder ─────────────────────────────────────────────────────────────────

export function buildProposalModel(input: BuildProposalInput): DocumentModel {
  const { vehicle, photos, settings = {}, template = "minimal" } = input;
  const lang: Lang = settings.language === "russian" ? "ru" : "en";
  const L = LABELS[lang];
  const theme = getTheme(template);
  const specs = vehicle.specs ?? {};

  const now = new Date().toLocaleDateString(lang === "ru" ? "ru-RU" : "en-GB", {
    day: "numeric",
    month: "long",
    year: "numeric",
  });

  const contact: ProposalContact = { ...DEFAULT_CONTACT, ...input.contact };

  // Cover photo: first validated external photo, fallback to main image if https
  const coverPhoto =
    photos[0] ??
    (typeof vehicle.image === "string" && vehicle.image.startsWith("https")
      ? vehicle.image
      : undefined);

  // Cover stat cells (up to 4)
  const coverCells: { label: string; value: string }[] = [];
  if (specs["length"])
    coverCells.push({ label: L["length"], value: specs["length"] });
  if (specs["guests"])
    coverCells.push({ label: L["guests"], value: specs["guests"] });
  if (specs["cabins"])
    coverCells.push({ label: L["cabins"], value: specs["cabins"] });
  if (specs["yearBuilt"])
    coverCells.push({ label: L["yearBuilt"], value: specs["yearBuilt"] });

  // ── body nodes ──────────────────────────────────────────────────────────────

  const body: ContentNode[] = [];

  // Page 1 — Specifications
  const specRows = SPEC_KEYS.map((k) => ({
    label: L[k] ?? k,
    value: specs[k] ? fmtVal(k, String(specs[k])) : "",
  })).filter((r) => r.value);

  if (specRows.length) {
    body.push({
      kind: "keyValue",
      heading: L["specifications"],
      rows: specRows,
      layout: "pairs",
    });
  }

  const descriptionText = stripHtml(
    specs["fullDescription"] || vehicle.description || "",
  );
  if (descriptionText) {
    body.push({
      kind: "paragraph",
      text: descriptionText,
      panel: true,
    });
  }

  // Page 2 — Photo gallery (breakBefore so it always starts fresh)
  const galleryUrls = photos.length
    ? photos
    : (vehicle.images ?? []).filter(
        (u) => typeof u === "string" && u.startsWith("https"),
      );

  if (galleryUrls.length) {
    body.push({
      kind: "gallery",
      heading: L["gallery"],
      images: galleryUrls.map((url) => ({ url })),
      columns: 3,
    });
  }

  // Page 3 — Contact (breakBefore so it starts on a fresh page)
  const contactRows: { label: string; value: string }[] = [
    contact.phone
      ? { label: L["phone"], value: stripHtml(contact.phone) }
      : null,
    contact.whatsapp
      ? { label: L["whatsapp"], value: stripHtml(contact.whatsapp) }
      : null,
    contact.email
      ? { label: L["email"], value: stripHtml(contact.email) }
      : null,
    contact.website
      ? { label: L["website"], value: stripHtml(contact.website) }
      : null,
  ].filter((r): r is { label: string; value: string } => r !== null);

  body.push({
    kind: "paragraph",
    heading: L["contact"],
    text: L["contactDesc"],
    breakBefore: true,
  });

  if (contactRows.length) {
    body.push({
      kind: "keyValue",
      rows: contactRows,
      layout: "list",
      boxed: true,
    });
  }

  // ── assemble model ──────────────────────────────────────────────────────────

  return {
    meta: {
      type: "proposal",
      brand: "TRANSYACHTGROUP",
      title: L["generatedLabel"],
      language: lang,
      confidential: false,
      watermarkText: "",
      generatedAt: now,
    },
    theme,
    cover: {
      eyebrow: L["eyebrow"],
      name: stripHtml(vehicle.name),
      date: now,
      photoUrl: coverPhoto,
      logoUrl: LOGO_DATA_URI,
      cells: coverCells,
      price: specs["pricePerDay"]
        ? `${fmtVal("pricePerDay", specs["pricePerDay"])} / day`
        : undefined,
    },
    body,
  };
}

// ─── custom HTML renderer ────────────────────────────────────────────────────

/**
 * Render a complete A4 HTML document for the 2-layout proposal:
 *
 *   Page 1  — hero photo (top ~42 %) + name/price overlay + compact 2-column
 *             spec grid + description (CSS-clamped) + contact bar + footer
 *   Page 2+ — 2×2 photo gallery; last page expands photos to fill space
 *
 * Bypasses the generic block engine: the "everything on one fixed page"
 * constraint cannot be expressed as a sequence of document blocks.
 * The output HTML is fed directly to renderPdf() (Puppeteer).
 */
export function renderProposalHtml(input: BuildProposalInput): string {
  const {
    vehicle,
    photos,
    settings = {},
    template = "minimal",
    rentalDates,
    transferDetails,
    whiteLabel = false,
  } = input;
  const lang: Lang = settings.language === "russian" ? "ru" : "en";
  const L = LABELS[lang];
  const theme = getTheme(template);
  const t = theme;
  const specs = vehicle.specs ?? {};

  const now = new Date().toLocaleDateString(lang === "ru" ? "ru-RU" : "en-GB", {
    day: "numeric",
    month: "long",
    year: "numeric",
  });

  const contact: ProposalContact = { ...DEFAULT_CONTACT, ...input.contact };

  // Russian output prefers the vehicle's `translations.ru.*` fields (filled
  // in by the admin's translate tool) and falls back to the base English
  // field whenever a translation is missing.
  const ruField = (key: string): string | undefined => {
    const v = vehicle.translations?.ru?.[key];
    return typeof v === "string" && v.trim() ? v : undefined;
  };
  const localizedName = (lang === "ru" && ruField("name")) || vehicle.name;
  const localizedDescription =
    (lang === "ru" && ruField("description")) || vehicle.description || "";
  const localizedFullDescription =
    (lang === "ru" && ruField("fullDescription")) ||
    specs["fullDescription"] ||
    "";

  // Hero: first validated photo, else main vehicle image
  const rawHeroPhoto =
    photos[0] ??
    (typeof vehicle.image === "string" && vehicle.image.startsWith("https")
      ? vehicle.image
      : undefined);
  const heroPhoto = rawHeroPhoto
    ? compressPhotoUrl(rawHeroPhoto, 1400)
    : undefined;

  // Gallery: skip photo[0] — already used as hero
  const allPhotos = photos.length
    ? photos
    : (vehicle.images ?? []).filter(
        (u): u is string => typeof u === "string" && u.startsWith("https"),
      );
  const galleryPhotos = allPhotos
    .slice(1)
    .map((u) => compressPhotoUrl(u, 1000));

  // Spec grid — pricePerDay used to be excluded here because the hero
  // overlay always showed it; now the hero only shows a price when a
  // specific rental quote is attached, so it belongs in the grid like any
  // other pricing spec (pricePerWeek, deposit, etc.) or it'd vanish entirely
  // on proposals with no quote (the public route).
  // kmIncluded is a per-day allowance — once a daily rental quote is
  // attached, show the total for the whole period rather than the bare
  // per-day figure. Only meaningful in "daily" mode: "periods" is a month
  // count in "monthly" mode, which isn't the day count this needs.
  const specRows = SPEC_KEYS.map((k) => {
    if (k === "kmIncluded" && rentalDates?.mode === "daily") {
      const perDay = parseInt(stripHtml(specs.kmIncluded).trim(), 10);
      if (Number.isFinite(perDay) && perDay > 0) {
        const total = perDay * rentalDates.periods;
        return {
          label: L[k] ?? k,
          value: `${total} km ${L["total"].toLowerCase()} (${rentalDates.periods} ${L["days"]} × ${perDay} km/day)`,
        };
      }
    }
    return {
      label: L[k] ?? k,
      value: specs[k] ? fmtVal(k, String(specs[k])) : "",
    };
  }).filter((r) => r.value);

  const descText = stripHtml(localizedFullDescription || localizedDescription);

  // The cover only ever shows a price when an admin has attached a specific
  // rental quote (dates + rate) — no generic spec-sheet price line, and
  // nothing at all on the public route, which never sets rentalDates.
  const rentalBlock = rentalDates
    ? {
        // Pickup/return locations take over the date/time line entirely (as
        // two lines, one per leg) once both locations and both times are
        // set; otherwise fall back to the single combined line, or just the
        // bare date range if even the times are missing.
        dateLines:
          rentalDates.pickupLocation &&
          rentalDates.returnLocation &&
          rentalDates.pickupTime &&
          rentalDates.returnTime
            ? [
                `${L["pickup"]}: ${rentalDates.pickupLocation} · ${formatDateShort(rentalDates.start, lang)}, ${rentalDates.pickupTime}`,
                `${L["return"]}: ${rentalDates.returnLocation} · ${formatDateShort(rentalDates.end, lang)}, ${rentalDates.returnTime}`,
              ]
            : [
                rentalDates.pickupTime && rentalDates.returnTime
                  ? `${formatDateShort(rentalDates.start, lang)}, ${rentalDates.pickupTime} → ${formatDateShort(rentalDates.end, lang)}, ${rentalDates.returnTime} · ${rentalDates.periods} ${rentalDates.mode === "monthly" ? L["months"] : L["days"]}`
                  : formatDateRange(rentalDates.start, rentalDates.end, lang),
              ],
        summaryLine: `${rentalDates.periods} ${rentalDates.mode === "monthly" ? L["months"] : L["days"]} · ${fmtEur(rentalDates.total, lang)} ${L["total"].toLowerCase()}`,
      }
    : undefined;

  // A transfer booking is mutually exclusive with a rental quote — the admin
  // form only ever sends one or the other — so this takes priority below.
  const transferBlock = transferDetails
    ? {
        route: `${transferDetails.from} → ${transferDetails.to}`,
        dateTimeLine: `${formatSingleDate(transferDetails.date, lang)} · ${transferDetails.time}`,
        passengersLine: `${transferDetails.passengers} ${L["passengers"].toLowerCase()}`,
        priceLine: fmtEur(transferDetails.price, lang),
      }
    : undefined;

  const heroDesc = (() => {
    const tagline = stripHtml(specs["tagline"] || specs["slogan"] || "");
    if (tagline)
      return tagline.length > 100
        ? tagline.slice(0, 99).trimEnd() + "…"
        : tagline;
    const raw = stripHtml(localizedDescription);
    if (!raw) return undefined;
    const sentences = raw.match(/[^.!?]+[.!?]+/g) || [raw];
    const result = sentences[0].trim();
    return result.length > 100 ? result.slice(0, 99).trimEnd() + "…" : result;
  })();

  const contactItems = (
    [
      contact.phone
        ? { label: L["phone"], value: stripHtml(contact.phone) }
        : null,
      contact.whatsapp
        ? { label: L["whatsapp"], value: stripHtml(contact.whatsapp) }
        : null,
      contact.email
        ? { label: L["email"], value: stripHtml(contact.email) }
        : null,
      contact.website
        ? { label: L["website"], value: stripHtml(contact.website) }
        : null,
    ] as Array<{ label: string; value: string } | null>
  ).filter((r): r is { label: string; value: string } => r !== null);

  const PHOTOS_PER_PAGE = 4;
  const galleryPageCount =
    galleryPhotos.length > 0
      ? Math.ceil(galleryPhotos.length / PHOTOS_PER_PAGE)
      : 0;
  const totalPages = 1 + galleryPageCount;

  const HEAD = `'Porter FT', 'Wix MadeFor Display', -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif`;

  // ── Proposal-specific CSS ──────────────────────────────────────────────────
  const proposalCss = `
    .prop-page {
      page-break-after: always;
      position: relative;
      height: 261mm;
      overflow: hidden;
      padding: 4mm 0 12mm;
    }
    .prop-page:last-child { page-break-after: auto; }
    .prop-logo { height: 9mm; width: auto; object-fit: contain; display: block; }
    .prop-date {
      font-family: ${HEAD};
      font-size: 8px;
      letter-spacing: 1.5px;
      text-transform: uppercase;
      color: ${t.textMuted};
    }
    /* ── Info page ── */
    .prop-info {
      display: flex;
      flex-direction: column;
      height: 100%;
      min-height: 0;
      gap: 2.5mm;
    }
    .prop-info-hdr {
      display: flex;
      justify-content: space-between;
      align-items: center;
      flex-shrink: 0;
      height: 10mm;
    }
    .prop-hero {
      position: relative;
      flex: 1;
      min-height: 80mm;
      overflow: hidden;
      border-radius: 2px;
      background: ${t.coverBg};
    }
    .prop-hero-img {
      position: absolute;
      inset: 0;
      width: 100%;
      height: 100%;
      object-fit: cover;
      display: block;
    }
    .prop-hero-overlay {
      position: absolute;
      bottom: 0; left: 0; right: 0;
      padding: 10mm 5mm 4mm;
      background: linear-gradient(transparent, rgba(10,10,10,0.85));
    }
    .prop-hero-name {
      font-family: ${HEAD};
      font-size: 22px;
      font-weight: 800;
      color: #fff;
      line-height: 1.1;
      margin: 0 0 2px;
    }
    .prop-hero-route {
      font-family: ${HEAD};
      font-size: 16px;
      font-weight: 700;
      color: #fff;
      line-height: 1.2;
      margin: 2px 0 2px;
    }
    .prop-hero-desc {
      font-family: ${HEAD};
      font-size: 11px;
      font-weight: 300;
      color: rgba(255,255,255,0.70);
      line-height: 1.4;
      margin: 3px 0 4px;
    }
    .prop-hero-price {
      font-family: ${HEAD};
      font-size: 12px;
      font-weight: 700;
      color: ${t.accent};
      margin: 0;
    }
    /* Spec grid */
    .prop-sec-label {
      font-family: ${HEAD};
      color: ${t.accentInk};
      font-size: 8px;
      letter-spacing: 1.4px;
      font-weight: 700;
      text-transform: uppercase;
      border-bottom: 1px solid ${t.accent};
      padding-bottom: 3px;
      margin-bottom: 2px;
      flex-shrink: 0;
    }
    table.prop-spec {
      width: 100%;
      border-collapse: collapse;
      flex-shrink: 0;
    }
    table.prop-spec td { padding: 2.5px 4px; vertical-align: top; font-size: 9px; }
    table.prop-spec tr:nth-child(even) td { background: ${t.rowAlt}; }
    .ps-l {
      font-family: ${HEAD};
      color: ${t.accentInk};
      font-size: 7.5px;
      letter-spacing: 0.8px;
      text-transform: uppercase;
      font-weight: 700;
      width: 20%;
    }
    .ps-v { font-weight: 500; color: ${t.text}; width: 30%; }
    /* Description */
    .prop-desc {
      margin: 0;
      font-size: 9px;
      line-height: 1.45;
      color: ${t.text};
      overflow: hidden;
      display: -webkit-box;
      -webkit-line-clamp: 5;
      -webkit-box-orient: vertical;
      flex-shrink: 0;
      background: ${t.panelBg};
      border-left: 3px solid ${t.accent};
      padding: 3mm 4mm;
      border-radius: 2px;
    }
    /* Contact bar */
    .prop-contact {
      display: flex;
      flex-wrap: wrap;
      gap: 2px 8px;
      align-items: center;
      background: ${t.coverBg};
      padding: 3mm 4mm;
      border-radius: 2px;
      flex-shrink: 0;
    }
    .prop-ct-item { display: inline-flex; align-items: center; gap: 4px; }
    .prop-ct-l {
      font-family: ${HEAD};
      color: ${t.coverAccent};
      font-size: 7px;
      letter-spacing: 0.8px;
      text-transform: uppercase;
      font-weight: 700;
    }
    .prop-ct-v { color: rgba(255,255,255,0.85); font-size: 8.5px; font-weight: 500; }
    .prop-ct-sep { color: ${t.accent}; margin: 0 3px; font-weight: 700; font-size: 9px; }
    /* ── Gallery pages ── */
    .prop-gal-wrap {
      display: flex;
      flex-direction: column;
      min-height: 0;
    }
    .prop-gal-hdr {
      display: flex;
      justify-content: space-between;
      align-items: center;
      flex-shrink: 0;
      height: 10mm;
      margin-bottom: 2.5mm;
    }
    .prop-gal-title {
      font-family: ${HEAD};
      font-size: 9px;
      letter-spacing: 1.4px;
      font-weight: 700;
      text-transform: uppercase;
      color: ${t.accentInk};
    }
    .prop-gallery-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      grid-auto-rows: 1fr;
      gap: 3mm;
      position: absolute;
      top: 22mm;
      bottom: 14mm;
      left: 0;
      right: 0;
    }
    .prop-gal-cell {
      background: #ffffff;
      border-radius: 2px;
      overflow: hidden;
      display: flex;
      align-items: center;
      justify-content: center;
      min-height: 0;
    }
    .prop-gal-img {
      width: 100%;
      height: 100%;
      object-fit: contain;
      display: block;
    }
  `;

  // ── Inner builders ────────────────────────────────────────────────────────

  function specGrid(): string {
    if (!specRows.length) return "";
    const rows: string[] = [];
    for (let i = 0; i < specRows.length; i += 2) {
      const a = specRows[i]!;
      const b = specRows[i + 1];
      rows.push(
        `<tr>` +
          `<td class="ps-l">${esc(a.label)}</td><td class="ps-v">${esc(a.value)}</td>` +
          `<td class="ps-l">${b ? esc(b.label) : ""}</td><td class="ps-v">${b ? esc(b.value) : ""}</td>` +
          `</tr>`,
      );
    }
    return (
      `<div class="prop-sec-label">${esc(L["specifications"])}</div>` +
      `<table class="prop-spec">${rows.join("")}</table>`
    );
  }

  function galleryGrid(batch: string[]): string {
    const count = batch.length;
    return (
      `<div class="prop-gallery-grid">` +
      batch
        .map((url, idx) => {
          const spanFull = count === 1 || (count === 3 && idx === 2);
          const extra = spanFull ? ` style="grid-column:1/-1"` : "";
          return (
            `<div class="prop-gal-cell"${extra}>` +
            `<img class="prop-gal-img" src="${esc(url)}" />` +
            `</div>`
          );
        })
        .join("") +
      `</div>`
    );
  }

  function pageFooter(pageNum: number): string {
    return (
      `<div class="page-footer">` +
      (whiteLabel
        ? `<span></span>`
        : `<span><span class="pf-brand">TRANSYACHTGROUP</span></span>`) +
      `<span>Page ${pageNum} of ${totalPages} · ${esc(now)}</span>` +
      `</div>`
    );
  }

  const logoHtml =
    !whiteLabel && LOGO_DATA_URI
      ? `<img class="prop-logo" src="${LOGO_DATA_URI}" />`
      : `<span></span>`;

  // ── Page 1: info ──────────────────────────────────────────────────────────

  const contactHtml =
    !whiteLabel && contactItems.length
      ? `<div class="prop-contact">` +
        contactItems
          .map(
            (it, i) =>
              (i > 0 ? `<span class="prop-ct-sep">·</span>` : "") +
              `<span class="prop-ct-item">` +
              `<span class="prop-ct-l">${esc(it.label)}</span> ` +
              `<span class="prop-ct-v">${esc(it.value)}</span>` +
              `</span>`,
          )
          .join("") +
        `</div>`
      : "";

  const infoPage =
    `<section class="prop-page">\n` +
    `<div class="prop-info">\n` +
    `  <div class="prop-info-hdr">${logoHtml}<span class="prop-date">${esc(now)}</span></div>\n` +
    `  <div class="prop-hero">\n` +
    (heroPhoto
      ? `    <img class="prop-hero-img" src="${esc(heroPhoto)}" />\n`
      : "") +
    `    <div class="prop-hero-overlay">\n` +
    `      <div class="prop-hero-name">${esc(stripHtml(localizedName))}</div>\n` +
    (heroDesc
      ? `      <div class="prop-hero-desc">${esc(heroDesc)}</div>\n`
      : "") +
    (transferBlock
      ? `      <div class="prop-hero-route">${esc(transferBlock.route)}</div>\n` +
        `      <div class="prop-hero-desc">${esc(transferBlock.dateTimeLine)}</div>\n` +
        `      <div class="prop-hero-desc">${esc(transferBlock.passengersLine)}</div>\n` +
        `      <div class="prop-hero-price">${esc(transferBlock.priceLine)}</div>\n`
      : rentalBlock
        ? rentalBlock.dateLines
            .map(
              (line) =>
                `      <div class="prop-hero-desc">${esc(line)}</div>\n`,
            )
            .join("") +
          `      <div class="prop-hero-price">${esc(rentalBlock.summaryLine)}</div>\n`
        : "") +
    `    </div>\n` +
    `  </div>\n` +
    `  ${specGrid()}\n` +
    (descText
      ? `  <p class="prop-desc">${esc(descText).replace(/\n/g, "<br/>")}</p>\n`
      : "") +
    `  ${contactHtml}\n` +
    `</div>\n` +
    pageFooter(1) +
    "\n" +
    `</section>`;

  // ── Gallery pages ─────────────────────────────────────────────────────────

  const galleryPageHtmls: string[] = [];
  for (let i = 0; i < galleryPhotos.length; i += PHOTOS_PER_PAGE) {
    const batch = galleryPhotos.slice(i, i + PHOTOS_PER_PAGE);
    const pageNum = 2 + Math.floor(i / PHOTOS_PER_PAGE);
    galleryPageHtmls.push(
      `<section class="prop-page">\n` +
        `<div class="prop-gal-wrap">\n` +
        `  <div class="prop-gal-hdr">\n` +
        `    ${logoHtml}\n` +
        `    <span class="prop-gal-title">${esc(L["gallery"])}</span>\n` +
        `    <span class="prop-date">${esc(now)}</span>\n` +
        `  </div>\n` +
        `  ${galleryGrid(batch)}\n` +
        `</div>\n` +
        pageFooter(pageNum) +
        "\n" +
        `</section>`,
    );
  }

  // ── Assemble ──────────────────────────────────────────────────────────────

  const pages = [infoPage, ...galleryPageHtmls].join("\n");
  return (
    `<!doctype html>\n<html><head><meta charset="utf-8" /><style>\n` +
    adaptiveCss(theme, false) +
    `\n` +
    proposalCss +
    `\n` +
    `</style></head>\n<body>\n${pages}\n</body></html>`
  );
}
